namespace sv_2643b30f1e484383889692bb0f605c38.Services;

/// <summary>
/// Scoped service that holds low-stock alert state for the current circuit.
/// Any component can subscribe to <see cref="OnChange"/> to react when new
/// alert data arrives — even components that did not trigger the refresh.
/// </summary>
public class InventoryAlertService
{
    private int _lowStockCount;

    public int LowStockCount => _lowStockCount;

    public event Action? OnChange;

    public async Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query
        await Task.Delay(100);
        return Random.Shared.Next(0, 16);
    }

    public async Task RefreshAsync(string warehouseId)
    {
        _lowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

