@page "/dashboard"
@rendermode InteractiveServer
@using sv_2643b30f1e484383889692bb0f605c38.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

@if (Warehouse is not null)
{
    <p class="lead">
        Viewing: <strong>@Warehouse.WarehouseName</strong>
        <span class="text-muted">(@Warehouse.WarehouseId)</span>
    </p>
}

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
                @if (_polling)
                {
                    <span class="badge bg-info">Polling every 10 s</span>
                }
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe so this component re-renders when any polling cycle completes,
        // even if the poll was triggered by our own timer callback.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        // Fires on first render AND whenever the cascaded warehouse changes.
        await RestartPollingAsync();
    }

    private bool _polling;

    private async Task RestartPollingAsync()
    {
        await StopPollingAsync();

        if (Warehouse is null) return;

        // Immediate first fetch
        await AlertService.RefreshAsync(Warehouse.WarehouseId);

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _polling = true;

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                if (Warehouse is not null)
                {
                    await AlertService.RefreshAsync(Warehouse.WarehouseId);
                }
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / warehouse switch
        }
    }

    private async Task StopPollingAsync()
    {
        _polling = false;
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

